// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// Simple buyer-funded escrow (single order)
contract SimpleEscrow {
    address public buyer;
    address payable public seller;
    uint256 public amount;
    bool public isFunded;
    bool public isReleased;
    bool public isRefunded;

    event Funded(address indexed buyer, uint256 amount);
    event Released(address indexed seller, uint256 amount);
    event Refunded(address indexed buyer, uint256 amount);

    constructor(address payable _seller) {
        require(_seller != address(0), "invalid seller");
        seller = _seller;
    }

    // Buyer funds the escrow (one-time)
    function fund() external payable {
        require(!isFunded, "already funded");
        require(msg.value > 0, "no funds sent");
        buyer = msg.sender;
        amount = msg.value;
        isFunded = true;
        emit Funded(buyer, amount);
    }

    // Buyer confirms delivery -> release to seller
    function confirmDelivery() external {
        require(isFunded, "not funded");
        require(!isReleased && !isRefunded, "already resolved");
        require(msg.sender == buyer, "only buyer");
        isReleased = true;
        seller.transfer(amount);
        emit Released(seller, amount);
    }

    // Buyer can request refund if delivery not confirmed
    function refundBuyer() external {
        require(isFunded, "not funded");
        require(!isReleased && !isRefunded, "already resolved");
        require(msg.sender == buyer, "only buyer");
        isRefunded = true;
        payable(buyer).transfer(amount);
        emit Refunded(buyer, amount);
    }
}
